import{_ as t,o as i,c as n,ag as a}from"./chunks/framework.BpFM782D.js";const p=JSON.parse('{"title":"frontend-design","description":"","frontmatter":{},"headers":[],"relativePath":"skills/frontend-design.md","filePath":"skills/frontend-design.md"}'),o={name:"skills/frontend-design.md"};function s(r,e,l,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="frontend-design" tabindex="-1">frontend-design <a class="header-anchor" href="#frontend-design" aria-label="Permalink to &quot;frontend-design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>frontend-design</td></tr><tr><td>說明</td><td>Create distinctive, production-grade frontend interfaces with high design quality. Use this skill when the user asks to build web components, pages, artifacts, posters, or applications (examples include websites, landing pages, dashboards, React components, HTML/CSS layouts, or when styling/beautifying any web UI). Generates creative, polished code and UI design that avoids generic AI aesthetics.</td></tr><tr><td>來源目錄</td><td><code>skills/frontend-design/</code></td></tr></tbody></table><hr><p>This skill guides creation of distinctive, production-grade frontend interfaces that avoid generic &quot;AI slop&quot; aesthetics. Implement real working code with exceptional attention to aesthetic details and creative choices.</p><p>The user provides frontend requirements: a component, page, application, or interface to build. They may include context about the purpose, audience, or technical constraints.</p><h2 id="design-thinking" tabindex="-1">Design Thinking <a class="header-anchor" href="#design-thinking" aria-label="Permalink to &quot;Design Thinking&quot;">​</a></h2><p>Before coding, understand the context and commit to a BOLD aesthetic direction:</p><ul><li><strong>Purpose</strong>: What problem does this interface solve? Who uses it?</li><li><strong>Tone</strong>: Pick an extreme: brutally minimal, maximalist chaos, retro-futuristic, organic/natural, luxury/refined, playful/toy-like, editorial/magazine, brutalist/raw, art deco/geometric, soft/pastel, industrial/utilitarian, etc. There are so many flavors to choose from. Use these for inspiration but design one that is true to the aesthetic direction.</li><li><strong>Constraints</strong>: Technical requirements (framework, performance, accessibility).</li><li><strong>Differentiation</strong>: What makes this UNFORGETTABLE? What&#39;s the one thing someone will remember?</li></ul><p><strong>CRITICAL</strong>: Choose a clear conceptual direction and execute it with precision. Bold maximalism and refined minimalism both work - the key is intentionality, not intensity.</p><p>Then implement working code (HTML/CSS/JS, React, Vue, etc.) that is:</p><ul><li>Production-grade and functional</li><li>Visually striking and memorable</li><li>Cohesive with a clear aesthetic point-of-view</li><li>Meticulously refined in every detail</li></ul><h2 id="frontend-aesthetics-guidelines" tabindex="-1">Frontend Aesthetics Guidelines <a class="header-anchor" href="#frontend-aesthetics-guidelines" aria-label="Permalink to &quot;Frontend Aesthetics Guidelines&quot;">​</a></h2><p>Focus on:</p><ul><li><strong>Typography</strong>: Choose fonts that are beautiful, unique, and interesting. Avoid generic fonts like Arial and Inter; opt instead for distinctive choices that elevate the frontend&#39;s aesthetics; unexpected, characterful font choices. Pair a distinctive display font with a refined body font.</li><li><strong>Color &amp; Theme</strong>: Commit to a cohesive aesthetic. Use CSS variables for consistency. Dominant colors with sharp accents outperform timid, evenly-distributed palettes.</li><li><strong>Motion</strong>: Use animations for effects and micro-interactions. Prioritize CSS-only solutions for HTML. Use Motion library for React when available. Focus on high-impact moments: one well-orchestrated page load with staggered reveals (animation-delay) creates more delight than scattered micro-interactions. Use scroll-triggering and hover states that surprise.</li><li><strong>Spatial Composition</strong>: Unexpected layouts. Asymmetry. Overlap. Diagonal flow. Grid-breaking elements. Generous negative space OR controlled density.</li><li><strong>Backgrounds &amp; Visual Details</strong>: Create atmosphere and depth rather than defaulting to solid colors. Add contextual effects and textures that match the overall aesthetic. Apply creative forms like gradient meshes, noise textures, geometric patterns, layered transparencies, dramatic shadows, decorative borders, custom cursors, and grain overlays.</li></ul><p>NEVER use generic AI-generated aesthetics like overused font families (Inter, Roboto, Arial, system fonts), cliched color schemes (particularly purple gradients on white backgrounds), predictable layouts and component patterns, and cookie-cutter design that lacks context-specific character.</p><p>Interpret creatively and make unexpected choices that feel genuinely designed for the context. No design should be the same. Vary between light and dark themes, different fonts, different aesthetics. NEVER converge on common choices (Space Grotesk, for example) across generations.</p><p><strong>IMPORTANT</strong>: Match implementation complexity to the aesthetic vision. Maximalist designs need elaborate code with extensive animations and effects. Minimalist or refined designs need restraint, precision, and careful attention to spacing, typography, and subtle details. Elegance comes from executing the vision well.</p><p>Remember: Claude is capable of extraordinary creative work. Don&#39;t hold back, show what can truly be created when thinking outside the box and committing fully to a distinctive vision.</p>',18)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
